using System;
using System.Collections.Generic;
using System.IO;
using Misterio.Gameplay;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace Misterio.EditorTools
{
    /// <summary>
    /// Shared helpers for building the four playable floors. Every floor is generated by code so the
    /// scenes stay reproducible and can be rebuilt after any art change.
    /// </summary>
    public static class FloorSceneKit
    {
        public const string ScenesPath = "Assets/Scenes";

        /// <summary>Creates an empty scene with the standard diorama camera.</summary>
        public static Camera NewDioramaScene(string rootName, Color background, float orthographicSize,
                                             Vector2 position, string cameraName)
        {
            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

            var cameraObject = new GameObject(cameraName);
            var camera = cameraObject.AddComponent<Camera>();
            camera.tag = "MainCamera";
            camera.orthographic = true;
            camera.orthographicSize = orthographicSize;
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = background;
            camera.nearClipPlane = 0.1f;
            camera.farClipPlane = 100f;
            camera.transform.position = new Vector3(position.x, position.y, -10f);
            cameraObject.AddComponent<AudioListener>();

            var root = new GameObject(rootName);
            root.transform.position = Vector3.zero;

            return camera;
        }

        /// <summary>Adds a background sprite scaled to cover the whole diorama.</summary>
        public static SpriteRenderer AddBackground(Camera camera, string spritePath, string name, int order = -20)
        {
            var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);
            if (sprite == null)
                throw new InvalidOperationException("Missing background sprite: " + spritePath);

            var host = new GameObject(name);
            var renderer = host.AddComponent<SpriteRenderer>();
            renderer.sprite = sprite;
            renderer.sortingOrder = order;
            host.transform.position = new Vector3(camera.transform.position.x, camera.transform.position.y, 5f);

            // Scale so the sprite covers the camera's vertical and horizontal extent.
            Vector3 size = sprite.bounds.size;
            float cameraHeight = camera.orthographicSize * 2f;
            float cameraWidth = cameraHeight * camera.aspect;
            if (size.x > 0.001f && size.y > 0.001f)
            {
                float scale = Mathf.Max(cameraWidth / size.x, cameraHeight / size.y);
                host.transform.localScale = new Vector3(scale, scale, 1f);
            }
            return renderer;
        }

        /// <summary>Adds the guard with its animation frames and collision setup.</summary>
        public static GuardActor AddGuard(Vector2 position, float scale = 0.48f)
        {
            var host = new GameObject("Segurança - jogador");
            host.transform.position = new Vector3(position.x, position.y, 0f);
            host.transform.localScale = new Vector3(scale, scale, 1f);

            var renderer = host.AddComponent<SpriteRenderer>();
            renderer.sortingOrder = 10;
            renderer.sprite = LoadFrame("GuardIdleFront", 0);

            var actor = host.AddComponent<GuardActor>();
            var serialized = new SerializedObject(actor);
            serialized.FindProperty("inputActions").objectReferenceValue =
                AssetDatabase.LoadAssetAtPath<UnityEngine.InputSystem.InputActionAsset>("Assets/InputSystem_Actions.inputactions");
            serialized.FindProperty("spriteRenderer").objectReferenceValue = renderer;
            SetFrames(serialized.FindProperty("idleFront"), "GuardIdleFront", 5);
            SetFrames(serialized.FindProperty("idleBack"), "GuardIdleBack", 5);
            SetFrames(serialized.FindProperty("walkFront"), "GuardWalkFront", 8);
            SetFrames(serialized.FindProperty("walkBack"), "GuardWalkBack", 8);
            serialized.ApplyModifiedPropertiesWithoutUndo();
            return actor;
        }

        public static Sprite LoadFrame(string prefix, int index) =>
            AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Art/CC01/" + prefix + "_" + index.ToString("00") + ".asset");

        public static void SetFrames(SerializedProperty property, string prefix, int count)
        {
            property.arraySize = count;
            for (int i = 0; i < count; i++)
                property.GetArrayElementAtIndex(i).objectReferenceValue = LoadFrame(prefix, i);
        }

        /// <summary>Builds a flat coloured sprite at runtime-free edit time, used for placeholders.</summary>
        public static Sprite MakeSolidSprite(string assetPath, int width, int height, Color fill, Color? border = null)
        {
            var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
            Color edge = border ?? new Color(fill.r * 0.55f, fill.g * 0.55f, fill.b * 0.55f, 1f);
            for (int y = 0; y < height; y++)
                for (int x = 0; x < width; x++)
                {
                    bool isEdge = x == 0 || y == 0 || x == width - 1 || y == height - 1;
                    texture.SetPixel(x, y, isEdge ? edge : fill);
                }
            texture.Apply();

            string directory = Path.GetDirectoryName(assetPath);
            if (!string.IsNullOrEmpty(directory) && !AssetDatabase.IsValidFolder(directory))
                CreateFolder(directory);

            File.WriteAllBytes(assetPath, texture.EncodeToPNG());
            UnityEngine.Object.DestroyImmediate(texture);
            AssetDatabase.ImportAsset(assetPath, ImportAssetOptions.ForceUpdate);

            var importer = AssetImporter.GetAtPath(assetPath) as TextureImporter;
            if (importer != null)
            {
                importer.textureType = TextureImporterType.Sprite;
                importer.spriteImportMode = SpriteImportMode.Single;
                importer.filterMode = FilterMode.Point;
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.spritePixelsPerUnit = 128f;
                importer.alphaIsTransparency = true;
                importer.SaveAndReimport();
            }
            return AssetDatabase.LoadAssetAtPath<Sprite>(assetPath);
        }

        public static Sprite MakePlaceholder(string assetName, Color color, int width = 24, int height = 24) =>
            MakeSolidSprite("Assets/Art/Placeholders/" + assetName + ".png", width, height, color);

        public static void CreateFolder(string path)
        {
            if (AssetDatabase.IsValidFolder(path)) return;
            string parent = Path.GetDirectoryName(path).Replace('\\', '/');
            string name = Path.GetFileName(path);
            if (!AssetDatabase.IsValidFolder(parent)) CreateFolder(parent);
            AssetDatabase.CreateFolder(parent, name);
        }

        public static void SaveAndRegister(string scenePath, bool buildSettings = true)
        {
            var scene = EditorSceneManager.GetActiveScene();
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, scenePath);
            if (buildSettings) AddSceneToBuildSettings(scenePath);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
        }

        public static void AddSceneToBuildSettings(string path)
        {
            var scenes = new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);
            foreach (var scene in scenes)
                if (scene.path == path) return;
            scenes.Add(new EditorBuildSettingsScene(path, true));
            EditorBuildSettings.scenes = scenes.ToArray();
        }

        public static void ApplyField(UnityEngine.Object target, string field, object value)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(field);
            if (property == null)
            {
                Debug.LogWarning("[FloorKit] missing field " + field + " on " + target.GetType().Name);
                return;
            }
            switch (value)
            {
                case UnityEngine.Object reference: property.objectReferenceValue = reference; break;
                case string text: property.stringValue = text; break;
                case bool flag: property.boolValue = flag; break;
                case int number: property.intValue = number; break;
                case float number: property.floatValue = number; break;
                case Vector2 vector: property.vector2Value = vector; break;
                case Vector3 vector: property.vector3Value = vector; break;
                case Color color: property.colorValue = color; break;
                case Rect rect: property.rectValue = rect; break;
                default:
                    Debug.LogWarning("[FloorKit] unsupported value for " + field);
                    break;
            }
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        public static void SetArray(UnityEngine.Object target, string field, UnityEngine.Object[] values)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(field);
            if (property == null) return;
            property.arraySize = values.Length;
            for (int i = 0; i < values.Length; i++)
                property.GetArrayElementAtIndex(i).objectReferenceValue = values[i];
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        public static void SetRectArray(UnityEngine.Object target, string field, Rect[] values)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(field);
            if (property == null) return;
            property.arraySize = values.Length;
            for (int i = 0; i < values.Length; i++)
                property.GetArrayElementAtIndex(i).rectValue = values[i];
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        public static void SetVector2Array(UnityEngine.Object target, string field, Vector2[] values)
        {
            var serialized = new SerializedObject(target);
            var property = serialized.FindProperty(field);
            if (property == null) return;
            property.arraySize = values.Length;
            for (int i = 0; i < values.Length; i++)
                property.GetArrayElementAtIndex(i).vector2Value = values[i];
            serialized.ApplyModifiedPropertiesWithoutUndo();
        }

        public static SpriteRenderer MakeSprite(string name, Sprite sprite, Vector2 position, int order, Transform parent = null)
        {
            var host = new GameObject(name);
            if (parent != null) host.transform.SetParent(parent, false);
            host.transform.position = new Vector3(position.x, position.y, 0f);
            var renderer = host.AddComponent<SpriteRenderer>();
            renderer.sprite = sprite;
            renderer.sortingOrder = order;
            return renderer;
        }

        /// <summary>Adds the night ambience and a one-shot effect source, reusing cutscene audio.</summary>
        public static (AudioSource ambient, AudioSource effects) AddAudio(string ambiencePath)
        {
            var host = new GameObject("Áudio do andar");
            var ambient = host.AddComponent<AudioSource>();
            ambient.loop = true;
            ambient.playOnAwake = true;
            ambient.volume = 0.20f;
            ambient.clip = AssetDatabase.LoadAssetAtPath<AudioClip>(ambiencePath);

            var effectsHost = new GameObject("Efeitos do andar");
            var effects = effectsHost.AddComponent<AudioSource>();
            effects.playOnAwake = false;
            effects.volume = 0.5f;
            return (ambient, effects);
        }
    }
}
